import hmac
import hashlib
import os
import time
import struct
from typing import Optional, Dict, List, Tuple

# Secure token-based session management system
# Tokens encode: [version(1)][timestamp(8)][user_id(4)][role(1)][permissions(2)][hmac(32)]

SECRET_KEY = os.urandom(32)
SESSION_STORE: Dict[int, dict] = {}
AUDIT_LOG: List[str] = []

ROLE_GUEST = 0
ROLE_USER = 1
ROLE_MODERATOR = 2
ROLE_ADMIN = 3

PERM_READ = 0x01
PERM_WRITE = 0x02
PERM_DELETE = 0x04
PERM_ADMIN = 0x08

# Permission matrix: role -> allowed permission mask
ROLE_PERMISSION_MATRIX = {
    ROLE_GUEST: PERM_READ,
    ROLE_USER: PERM_READ | PERM_WRITE,
    ROLE_MODERATOR: PERM_READ | PERM_WRITE | PERM_DELETE,
    ROLE_ADMIN: PERM_READ | PERM_WRITE | PERM_DELETE | PERM_ADMIN,
}

def compute_hmac(data: bytes) -> bytes:
    return hmac.new(SECRET_KEY, data, hashlib.sha256).digest()

def create_token(user_id: int, role: int, permissions: int) -> bytes:
    """Create a signed authentication token."""
    if role not in ROLE_PERMISSION_MATRIX:
        raise ValueError("Invalid role")
    allowed = ROLE_PERMISSION_MATRIX[role]
    if permissions & ~allowed:
        raise ValueError("Permissions exceed role allowance")

    version = b'\x01'
    timestamp = struct.pack('>Q', int(time.time()))
    uid = struct.pack('>I', user_id)
    role_byte = struct.pack('B', role)
    perm_bytes = struct.pack('>H', permissions)

    payload = version + timestamp + uid + role_byte + perm_bytes
    mac = compute_hmac(payload)
    return payload + mac

def parse_token(token: bytes) -> Optional[dict]:
    """Parse and validate a token. Returns None if invalid."""
    if len(token) != 48:  # 1 + 8 + 4 + 1 + 2 + 32
        return None

    payload = token[:16]
    provided_mac = token[16:]
    expected_mac = compute_hmac(payload)

    if not hmac.compare_digest(provided_mac, expected_mac):
        return None

    version = payload[0]
    if version != 1:
        return None

    timestamp = struct.unpack('>Q', payload[1:9])[0]
    # Token expires after 1 hour
    if time.time() - timestamp > 3600:
        return None

    user_id = struct.unpack('>I', payload[9:13])[0]
    role = payload[13]
    permissions = struct.unpack('>H', payload[14:16])[0]

    return {
        'user_id': user_id,
        'role': role,
        'permissions': permissions,
        'timestamp': timestamp
    }

def validate_permission_elevation(current_perms: int, requested_perms: int, role: int) -> bool:
    """Check if permission elevation request is valid for the given role."""
    allowed_mask = ROLE_PERMISSION_MATRIX.get(role, 0)
    combined = current_perms | requested_perms
    return (combined & ~allowed_mask) == 0

class ResourceACL:
    """Access control list for resources."""

    def __init__(self):
        self._acl: Dict[str, List[Tuple[int, int]]] = {}  # resource -> [(user_id, perm_mask)]
        self._resource_owners: Dict[str, int] = {}

    def create_resource(self, resource_id: str, owner_id: int):
        self._acl[resource_id] = [(owner_id, PERM_READ | PERM_WRITE | PERM_DELETE)]
        self._resource_owners[resource_id] = owner_id

    def grant_access(self, resource_id: str, grantor_token: bytes, 
                     target_user: int, permissions: int) -> bool:
        """Grant access to a resource. Grantor must have ADMIN perm or be owner."""
        token_data = parse_token(grantor_token)
        if token_data is None:
            return False

        grantor_id = token_data['user_id']
        grantor_perms = token_data['permissions']
        grantor_role = token_data['role']

        # Check: grantor must be owner or have admin permission
        is_owner = self._resource_owners.get(resource_id) == grantor_id
        has_admin = (grantor_perms & PERM_ADMIN) != 0

        if not (is_owner or has_admin):
            AUDIT_LOG.append(f"DENIED: User {grantor_id} tried to grant on {resource_id}")
            return False

        # Validate that granted permissions don't exceed what grantor can give
        if not is_owner and not validate_permission_elevation(permissions, 0, grantor_role):
            return False

        self._acl.setdefault(resource_id, []).append((target_user, permissions))
        AUDIT_LOG.append(f"GRANTED: User {grantor_id} gave {permissions} to {target_user} on {resource_id}")
        return True

    def check_access(self, resource_id: str, token: bytes, required_perm: int) -> bool:
        """Check if token holder has required permission on resource."""
        token_data = parse_token(token)
        if token_data is None:
            return False

        user_id = token_data['user_id']
        token_role = token_data['role']

        # Admin role bypasses ACL checks
        if token_role >= ROLE_ADMIN:
            return True

        entries = self._acl.get(resource_id, [])
        for (uid, mask) in entries:
            if uid == user_id and (mask & required_perm) == required_perm:
                return True

        return False

class SessionManager:
    """Manages user sessions with rate limiting."""

    def __init__(self, max_sessions_per_user: int = 5):
        self._sessions: Dict[int, List[dict]] = {}
        self._max = max_sessions_per_user
        self._login_attempts: Dict[int, List[float]] = {}

    def _check_rate_limit(self, user_id: int) -> bool:
        """Allow max 10 login attempts per minute."""
        now = time.time()
        attempts = self._login_attempts.get(user_id, [])
        # Remove attempts older than 60 seconds
        recent = [t for t in attempts if now - t < 60]
        self._login_attempts[user_id] = recent
        return len(recent) < 10

    def create_session(self, user_id: int, role: int, permissions: int) -> Optional[bytes]:
        """Create a new session. Returns token or None if rate limited."""
        if not self._check_rate_limit(user_id):
            AUDIT_LOG.append(f"RATE_LIMITED: User {user_id}")
            return None

        self._login_attempts.setdefault(user_id, []).append(time.time())

        # Enforce session limit - remove oldest if at max
        user_sessions = self._sessions.get(user_id, [])
        if len(user_sessions) >= self._max:
            user_sessions.pop(0)

        token = create_token(user_id, role, permissions)
        session_info = {
            'token_hash': hashlib.sha256(token).hexdigest(),
            'created': time.time(),
            'role': role,
            'permissions': permissions
        }
        self._sessions.setdefault(user_id, []).append(session_info)
        return token

    def revoke_session(self, admin_token: bytes, target_user: int, session_index: int) -> bool:
        """Admin can revoke a specific session of any user."""
        token_data = parse_token(admin_token)
        if token_data is None:
            return False

        # Only admins can revoke others' sessions
        if token_data['role'] < ROLE_ADMIN and token_data['user_id'] != target_user:
            return False

        user_sessions = self._sessions.get(target_user, [])
        # Bounds check using length comparison
        if session_index < len(user_sessions):
            removed = user_sessions.pop(session_index)
            AUDIT_LOG.append(f"REVOKED: session of user {target_user} by {token_data['user_id']}")
            return True

        return False

    def get_active_sessions(self, token: bytes) -> Optional[List[dict]]:
        """Get active sessions for the token's user."""
        token_data = parse_token(token)
        if token_data is None:
            return None
        return self._sessions.get(token_data['user_id'], [])


def handle_admin_action(session_mgr: SessionManager, acl: ResourceACL,
                        admin_token: bytes, action: str, params: dict) -> dict:
    """Process admin actions with full validation."""
    token_data = parse_token(admin_token)
    if token_data is None:
        return {'error': 'Invalid token'}

    if token_data['role'] < ROLE_ADMIN:
        AUDIT_LOG.append(f"UNAUTHORIZED: User {token_data['user_id']} attempted admin action {action}")
        return {'error': 'Insufficient privileges'}

    if action == 'revoke_session':
        target = params.get('target_user')
        idx = params.get('session_index', 0)
        if target is None:
            return {'error': 'Missing target_user'}
        success = session_mgr.revoke_session(admin_token, target, idx)
        return {'success': success}

    elif action == 'grant_resource':
        resource = params.get('resource_id')
        target = params.get('target_user')
        perms = params.get('permissions', PERM_READ)
        if not resource or target is None:
            return {'error': 'Missing parameters'}
        success = acl.grant_access(resource, admin_token, target, perms)
        return {'success': success}

    return {'error': 'Unknown action'}
